/* updateMasterMdCtReportCustomerList */
UPDATE KEP.KEP_REPORT
SET GROUP_NAME = #{st_report_nm}
, TR_YN = #{st_check_yn0}
, TR_TYPE = #{st_select0}
, TRDT_YN = #{st_check_yn1}
, TRDT_TYPE = #{st_select1}
, NEW_CONTRACT_YN = #{st_check_yn2}
, NEW_CONTRACT_TYPE = #{st_select2}
, PD_YN = #{st_check_yn3}
, PD_TYPE = #{st_select3}
, BUYER_CA_PD_YN = #{st_check_yn4}
, BUYER_CA_PD_TYPE = #{st_select4}
, RD_YN = #{st_check_yn5}
, RD_TYPE = #{st_select5}
, BUYER_CA_RD_YN = #{st_check_yn6}
, BUYER_CA_RD_TYPE = #{st_select6}
, DE_CD_YN = #{st_check_yn7}
