/* deleteMasterMdCtReportCustomerMng */
DELETE ICOMCOD2 A
WHERE A.TYPE = 'RPMP'
AND A.COMPANY_CODE = 'KRKORE0001'
AND A.TEXT1 =  #{st_group_cd}


/* delMasterMdCtReportCustomerList */
DELETE ICOMCOD2 A
WHERE A.TYPE = 'RPMP'
AND A.COMPANY_CODE = 'KRKORE0001'
AND A.TEXT1 = #{GROUP_CODE}
AND A.CODE =  #{COM_CODE}
